-- More built-in exercises for injury healing and prevention, so every body
-- region has a few options. Mid-back exercises are filed under upper_back,
-- which is where the injury body map looks for them.
insert into public.exercises
  (user_id, name, category, purposes, body_regions, dosage, equipment, description, steps, unilateral)
values
  -- Neck
  (null, 'Upper trap stretch', 'stretch', '{healing,prevention}', '{neck,shoulder}', '3 × 30 sec each side', null,
   'Eases tight muscles along the side of the neck and top of the shoulder, a common spot for desk tension.',
   '{"Sit tall and hold the edge of your chair with one hand to keep that shoulder down.","Tilt your ear toward the other shoulder.","For more stretch, rest your free hand on your head without pulling."}', true),
  (null, 'Levator scapulae stretch', 'stretch', '{healing,prevention}', '{neck,upper_back}', '3 × 30 sec each side', null,
   'Stretches the muscle that runs from the neck to the shoulder blade, often behind a stiff, hard-to-turn neck.',
   '{"Sit tall and hold the chair with one hand.","Turn your head 45° away from that side and look down toward your armpit.","Rest your other hand on the back of your head and let its weight deepen the stretch."}', true),
  (null, 'Neck rotation', 'mobility', '{healing}', '{neck}', '2 × 10 each direction', null,
   'Gently brings back turning range after a stiff or strained neck.',
   '{"Sit tall with your chin slightly tucked.","Turn your head slowly to look over one shoulder as far as is comfortable.","Return to center and turn the other way."}', false),
  (null, 'Prone head lift', 'strength', '{healing,prevention}', '{neck,upper_back}', '2 × 10, hold 5 sec', null,
   'Strengthens the muscles at the back of the neck, which tire out from looking down at screens.',
   '{"Lie face down with your forehead on a folded towel.","Tuck your chin slightly and lift your head an inch off the towel, keeping your eyes on the floor.","Hold, then lower slowly."}', false),

  -- Shoulder
  (null, 'Side-lying external rotation', 'strength', '{healing,prevention}', '{shoulder}', '3 × 12 each side', 'Light dumbbell',
   'Isolates the rotator cuff with very little load. Often one of the first strength exercises after a shoulder injury.',
   '{"Lie on your side with a rolled towel between your top elbow and your ribs.","With the elbow bent 90°, rotate the weight up toward the ceiling.","Lower slowly over about 3 seconds."}', true),
  (null, 'Sleeper stretch', 'stretch', '{prevention}', '{shoulder}', '3 × 30 sec each side', null,
   'Stretches the back of the shoulder, which tightens in throwers, swimmers and people who sleep on one side.',
   '{"Lie on your side with your bottom arm out in front at shoulder height, elbow bent 90°.","Use your top hand to gently press the bottom forearm toward the floor.","Stop at a stretch, not pain."}', true),
  (null, 'Cross-body shoulder stretch', 'stretch', '{prevention}', '{shoulder,upper_back}', '3 × 30 sec each side', null,
   'Loosens the back of the shoulder and the muscles between the shoulder blades.',
   '{"Bring one arm straight across your chest.","Hold it above the elbow with the other hand and pull it gently closer.","Keep the shoulder down, away from your ear."}', true),
  (null, 'Scaption raise', 'strength', '{healing,prevention}', '{shoulder}', '3 × 12', 'Light dumbbells',
   'Raises the arms in the plane the shoulder blade naturally moves in, strengthening the cuff and deltoid with less pinching than a side raise.',
   '{"Stand holding light weights, thumbs up.","Raise your arms to shoulder height at about 30° forward of straight out to the side, making a V.","Lower slowly."}', false),
  (null, 'Band shoulder pass-through', 'mobility', '{prevention}', '{shoulder,chest}', '2 × 10', 'Resistance band or stick',
   'Takes the shoulders through their full overhead range. A good warm-up before pressing or swimming.',
   '{"Hold a band or stick with a wide grip in front of your hips.","With straight arms, raise it overhead and behind you as far as is comfortable.","Bring it back the same way. Widen your grip if it pinches."}', false),
  (null, 'Shoulder flexion isometric', 'strength', '{healing}', '{shoulder}', '5 × 10 sec each direction, each side', null,
   'Wakes up the shoulder muscles without moving a painful joint. Useful in the first days after a strain.',
   '{"Stand facing a wall with your elbow bent 90° and your fist against the wall.","Press into the wall at about a third of your effort without moving.","Repeat pushing outward, inward and backward against the wall or door frame."}', true),

  -- Chest
  (null, 'Push-up plus', 'stability', '{prevention}', '{chest,shoulder}', '3 × 10', null,
   'A push-up with an extra push at the top that trains the serratus, keeping the shoulder blade snug to the ribs.',
   '{"Do a push-up from your knees or toes.","At the top, keep pushing to round your upper back slightly and spread your shoulder blades.","Lower and repeat."}', false),
  (null, 'Floor pec stretch', 'stretch', '{prevention}', '{chest,shoulder}', '3 × 30 sec each side', null,
   'Opens the chest and front of the shoulder without needing a doorway.',
   '{"Lie face down with one arm out to the side, elbow bent 90°.","Push up with your other hand and roll your body away from the outstretched arm.","Stop when you feel a stretch across the chest."}', true),

  -- Upper and mid back
  (null, 'Open book', 'mobility', '{healing,prevention}', '{upper_back,chest}', '2 × 10 each side', null,
   'Rotates the mid and upper back while keeping the lower back still.',
   '{"Lie on your side with hips and knees bent 90° and arms straight out in front.","Keep your knees together and sweep your top arm over to the other side, following it with your eyes.","Pause where it stretches, then return."}', true),
  (null, 'Thread the needle', 'mobility', '{healing,prevention}', '{upper_back,shoulder}', '2 × 8 each side', null,
   'Loosens the mid-back and the back of the shoulder, easing stiffness between the shoulder blades.',
   '{"Start on hands and knees.","Slide one arm under your body along the floor, letting that shoulder and your head drop.","Unwind and reach the same arm up toward the ceiling."}', true),
  (null, 'Band row', 'strength', '{healing,prevention}', '{upper_back,shoulder}', '3 × 15', 'Resistance band',
   'Strengthens the mid-back muscles that hold the shoulders back and the spine upright.',
   '{"Anchor a band at chest height and hold an end in each hand.","Pull your elbows back past your ribs, squeezing your shoulder blades together.","Return slowly without letting your shoulders round forward."}', false),
  (null, 'Single-arm dumbbell row', 'strength', '{prevention}', '{upper_back,shoulder,core}', '3 × 10 each side', 'Dumbbell and bench',
   'Builds the lats and mid-back while the core resists twisting.',
   '{"Place one knee and hand on a bench, back flat.","Row the weight toward your hip, keeping your torso still.","Lower slowly."}', true),
  (null, 'Prone shoulder blade squeeze', 'stability', '{healing,prevention}', '{upper_back}', '2 × 10, hold 5 sec', null,
   'Teaches the mid-back muscles to set the shoulder blades, a base for every pulling and pressing exercise.',
   '{"Lie face down with arms at your sides, palms down.","Draw your shoulder blades back and down and lift your hands an inch.","Hold without shrugging, then relax."}', false),
  (null, 'Seated thoracic extension', 'mobility', '{prevention}', '{upper_back}', '2 × 10', 'Chair',
   'Undoes a slumped mid-back without any equipment, handy during a workday.',
   '{"Sit on a chair with a backrest that hits below your shoulder blades.","Hands behind your head, gently arch your upper back over the backrest.","Return to upright and repeat."}', false),

  -- Lower back
  (null, 'Child''s pose', 'stretch', '{healing,prevention}', '{lower_back,hip}', '3 × 30 sec', null,
   'A gentle rest position that lengthens the lower back and hips.',
   '{"Kneel and sit back toward your heels.","Walk your hands forward and let your chest sink toward the floor.","Breathe slowly into your back."}', false),
  (null, 'Prone press-up', 'mobility', '{healing}', '{lower_back}', '2 × 10', null,
   'A McKenzie exercise that often eases low-back pain that is worse with sitting or bending.',
   '{"Lie face down with your hands under your shoulders.","Press your upper body up, letting your hips and lower back stay relaxed on the floor.","Go only as high as is comfortable, then lower. Stop if pain spreads down the leg."}', false),
  (null, 'Single knee to chest', 'stretch', '{healing}', '{lower_back,glute,hip}', '3 × 30 sec each side', null,
   'A gentle stretch for the lower back and buttock, easy to do in bed when the back is sore.',
   '{"Lie on your back with knees bent.","Hug one knee toward your chest with both hands.","Hold, then switch legs."}', true),
  (null, 'Pelvic tilt', 'mobility', '{healing}', '{lower_back,core}', '2 × 15', null,
   'Small, gentle movement for the lower back and a first step in learning to brace the core.',
   '{"Lie on your back with knees bent and feet flat.","Flatten your lower back into the floor by tightening your stomach and tipping your pelvis up.","Relax back to neutral."}', false),
  (null, 'Supine lumbar twist', 'stretch', '{healing,prevention}', '{lower_back,hip,glute}', '3 × 30 sec each side', null,
   'Lets the lower back and hips relax into a gentle rotation.',
   '{"Lie on your back with knees bent and arms out to the sides.","Let both knees drop to one side, keeping your shoulders on the floor.","Hold, then bring them back and switch."}', true),
  (null, 'Hip hinge with dowel', 'stability', '{healing,prevention}', '{lower_back,hamstring,hip}', '2 × 10', 'Broomstick or dowel',
   'Teaches bending from the hips with a neutral spine, protecting the lower back when lifting.',
   '{"Hold a stick along your spine touching your head, upper back and tailbone.","Push your hips back and tip forward, keeping all three points on the stick.","Stand back up by squeezing your glutes."}', false),

  -- Core
  (null, 'Front plank', 'stability', '{prevention}', '{core,lower_back,shoulder}', '3 × 20–45 sec', null,
   'Builds core endurance to hold the spine steady.',
   '{"Prop yourself on your forearms and toes (or knees, easier).","Squeeze your glutes and brace your stomach so your body is straight.","Hold without letting your hips sag or pike up."}', false),
  (null, 'Suitcase carry', 'stability', '{prevention}', '{core,lower_back,wrist_hand}', '3 × 30 m each side', 'Dumbbell or kettlebell',
   'Carrying a weight in one hand trains the side core to keep you upright. Great for back resilience.',
   '{"Hold a heavy weight in one hand at your side.","Walk tall without leaning toward or away from the weight.","Switch hands and walk back."}', true),
  (null, 'Bear hold', 'stability', '{prevention}', '{core,shoulder,quad}', '3 × 20–30 sec', null,
   'A low-impact full-body brace that builds core control with no strain on the lower back.',
   '{"Start on hands and knees, hands under shoulders and knees under hips.","Brace your stomach and lift your knees an inch off the floor.","Hold while breathing steadily, keeping your back flat."}', false),
  (null, 'Heel tap', 'stability', '{healing}', '{core,lower_back}', '3 × 10 each side', null,
   'An easier dead bug variation for regaining core control after back pain or pregnancy.',
   '{"Lie on your back with knees bent 90° over your hips.","Keeping your lower back gently pressed down, lower one heel to tap the floor.","Bring it back and switch legs."}', false),

  -- Elbow
  (null, 'Eccentric wrist flexion', 'strength', '{healing}', '{elbow,wrist_hand}', '3 × 15', 'Light dumbbell',
   'Slow lowering for the inner forearm tendons. The usual starting exercise for golfer''s elbow.',
   '{"Rest your forearm on your thigh, palm up, holding a light weight.","Use the other hand to help curl the weight up.","Lower it slowly with the sore wrist alone over about 3 seconds."}', true),
  (null, 'Forearm rotation', 'strength', '{healing,prevention}', '{elbow,wrist_hand}', '3 × 12 each side', 'Hammer or light dumbbell held at one end',
   'Strengthens the muscles that turn the forearm, which often weaken with elbow and wrist pain.',
   '{"Rest your forearm on a table with your hand off the edge, holding a hammer upright.","Slowly rotate your palm down, then back up and over to palm up.","Choke up on the handle to make it easier."}', true),
  (null, 'Tyler twist', 'strength', '{healing}', '{elbow,wrist_hand}', '3 × 15', 'FlexBar or rolled towel',
   'An eccentric twist shown to help tennis elbow.',
   '{"Hold a FlexBar upright in your sore hand with the wrist bent back.","Grab the top with your other hand and twist it so the bar is horizontal.","Slowly let the sore wrist untwist the bar over about 4 seconds."}', true),
  (null, 'Isometric wrist extension', 'strength', '{healing}', '{elbow,wrist_hand}', '5 × 45 sec', null,
   'A steady hold that can ease tennis elbow pain when moving it still hurts.',
   '{"Rest your forearm on a table, palm down.","Press the back of your hand up into your other hand without moving.","Hold at a strength that feels like work but not sharp pain."}', true),

  -- Wrist and hand
  (null, 'Tendon glides', 'mobility', '{healing,prevention}', '{wrist_hand}', '2 × 5 rounds each hand', null,
   'Moves the finger tendons through their full path. Helpful for carpal tunnel symptoms and stiff hands.',
   '{"Start with your fingers straight up.","Move through a hook fist, full fist, straight fist and tabletop, holding each for a few seconds.","Return to straight fingers between each."}', true),
  (null, 'Grip squeeze', 'strength', '{healing,prevention}', '{wrist_hand,elbow}', '3 × 10, hold 5 sec', 'Putty, stress ball or rolled towel',
   'Rebuilds grip strength after a wrist, hand or elbow injury.',
   '{"Hold a soft ball or putty in your palm.","Squeeze as hard as is comfortable.","Hold, then slowly relax."}', true),
  (null, 'Finger extension with band', 'strength', '{prevention}', '{wrist_hand,elbow}', '3 × 15', 'Rubber band',
   'Balances out gripping by strengthening the muscles that open the hand. Popular with climbers.',
   '{"Loop a rubber band around your fingertips and thumb.","Spread your fingers apart against the band.","Return slowly."}', true),
  (null, 'Wrist circles', 'mobility', '{healing,prevention}', '{wrist_hand}', '10 each direction', null,
   'A gentle warm-up for stiff wrists before typing, push-ups or lifting.',
   '{"Interlace your fingers or hold your arms out in front.","Roll your wrists in slow, full circles.","Switch direction."}', false),
  (null, 'Prayer stretch', 'stretch', '{prevention}', '{wrist_hand}', '3 × 30 sec', null,
   'Stretches the palm side of the wrists and forearms.',
   '{"Press your palms together in front of your chest, fingers up.","Keeping your palms together, slowly lower your hands toward your waist.","Stop when you feel a stretch and hold."}', false),

  -- Hip
  (null, 'Side-lying hip abduction', 'strength', '{healing,prevention}', '{hip,glute}', '3 × 12 each side', 'Ankle weight (optional)',
   'Strengthens the side glute, which steadies the pelvis and knee when standing on one leg.',
   '{"Lie on your side with your bottom knee bent and top leg straight.","Turn your top toes slightly down and lift the leg up and slightly back.","Lower slowly without rolling your hips back."}', true),
  (null, 'Fire hydrant', 'strength', '{prevention}', '{hip,glute}', '3 × 12 each side', 'Resistance band (optional)',
   'Works the outer hip in a bent-knee position.',
   '{"Start on hands and knees.","Keeping the knee bent, lift one leg out to the side without tipping your body.","Lower slowly."}', true),
  (null, 'Hip airplane', 'stability', '{prevention}', '{hip,glute,ankle_foot}', '2 × 5 each side', 'Wall or chair for balance',
   'Trains hip rotation control on one leg, useful for hip impingement and knee pain.',
   '{"Stand on one leg and hinge forward until your torso is level, other leg back.","Rotate your hips open toward the ceiling, then close them toward the floor.","Move slowly and keep your standing knee soft."}', true),
  (null, 'Pigeon stretch', 'stretch', '{prevention}', '{hip,glute}', '3 × 30 sec each side', null,
   'Deep stretch for the outer hip and glutes.',
   '{"From hands and knees, bring one knee forward behind your wrist, shin angled across.","Slide the other leg straight back.","Keep your hips square and lower your chest as far as is comfortable."}', true),
  (null, 'Adductor rock back', 'mobility', '{healing,prevention}', '{hip}', '2 × 10 each side', null,
   'Gently loosens the inner thigh and groin.',
   '{"Start on hands and knees and straighten one leg out to the side, foot flat.","Rock your hips back toward your heel until you feel the inner thigh stretch.","Rock forward and repeat."}', true),
  (null, 'Adductor squeeze', 'strength', '{healing}', '{hip}', '5 × 10 sec', 'Ball or pillow',
   'An isometric for the groin muscles. A common first exercise for groin strains and pubic pain.',
   '{"Lie on your back with knees bent and a ball between them.","Squeeze the ball at a comfortable effort.","Hold, then relax."}', false),
  (null, 'Lateral band walk', 'strength', '{prevention}', '{hip,glute,knee}', '3 × 10 steps each way', 'Mini band',
   'Strengthens the side glutes that keep the knees tracking straight.',
   '{"Place a mini band around your legs above the knees or at the ankles.","Get into a quarter squat with your feet hip-width apart.","Step sideways without letting your feet come together or knees cave in."}', false),

  -- Glutes
  (null, 'Single-leg glute bridge', 'strength', '{healing,prevention}', '{glute,hamstring,hip}', '3 × 10 each side', null,
   'A harder bridge that shows and fixes side-to-side strength differences.',
   '{"Lie on your back, one knee bent and the other leg straight or held to your chest.","Push through the planted heel to lift your hips level.","Lower slowly without letting the hips tilt."}', true),
  (null, 'Figure-4 stretch', 'stretch', '{healing,prevention}', '{glute,hip,lower_back}', '3 × 30 sec each side', null,
   'Stretches the deep glute muscles, including the piriformis, which can irritate the sciatic nerve.',
   '{"Lie on your back with knees bent.","Cross one ankle over the opposite knee.","Pull the bottom thigh toward your chest until you feel the stretch in the crossed side."}', true),
  (null, 'Hip thrust', 'strength', '{prevention}', '{glute,hamstring}', '3 × 10', 'Bench, weight optional',
   'Builds strong glutes to support the lower back and knees.',
   '{"Sit with your upper back against a bench, knees bent and feet flat.","Drive through your heels to lift your hips until your body is flat from shoulders to knees.","Squeeze at the top, then lower."}', false),

  -- Quads
  (null, 'Quad set', 'strength', '{healing}', '{quad,knee}', '3 × 10, hold 5 sec each side', 'Rolled towel',
   'The simplest way to switch the thigh back on after a knee injury or surgery.',
   '{"Sit with your leg straight and a rolled towel under the knee.","Tighten your thigh to press the back of your knee into the towel.","Hold, then relax."}', true),
  (null, 'Short arc quad', 'strength', '{healing}', '{quad,knee}', '3 × 12 each side', 'Foam roller or rolled towel',
   'Strengthens the quad over the last part of knee straightening with little stress on the joint.',
   '{"Lie with a roller or towel roll under one knee.","Straighten the knee by lifting your heel, keeping the back of the knee on the roll.","Hold for a second, then lower slowly."}', true),
  (null, 'Wall sit', 'strength', '{healing,prevention}', '{quad,knee,glute}', '3 × 30–45 sec', null,
   'An isometric hold that builds quad endurance and can calm knee tendon pain.',
   '{"Lean your back against a wall and slide down until your knees are bent to a comfortable depth.","Keep your knees over your ankles and weight in your heels.","Hold, then slide up."}', false),
  (null, 'Standing quad stretch', 'stretch', '{prevention}', '{quad,hip,knee}', '3 × 30 sec each side', null,
   'Stretches the front of the thigh and hip.',
   '{"Stand holding something for balance.","Grab one ankle behind you and bring your heel toward your buttock.","Keep your knees together and tuck your tailbone under."}', true),
  (null, 'Reverse Nordic', 'strength', '{prevention}', '{quad,knee}', '3 × 6', 'Mat',
   'Lengthens and strengthens the quads under load, helping prevent quad strains.',
   '{"Kneel upright with your body straight from knees to head.","Lean back slowly, keeping your hips straight, as far as you can control.","Squeeze your thighs to pull yourself back up."}', false),

  -- Hamstrings
  (null, 'Supine hamstring stretch', 'stretch', '{healing,prevention}', '{hamstring,lower_back}', '3 × 30 sec each side', 'Strap or towel',
   'Stretches the hamstrings without bending the lower back.',
   '{"Lie on your back with a strap around one foot.","Keep the leg straight and pull it up until you feel a stretch behind the thigh.","Keep the other leg relaxed on the floor."}', true),
  (null, 'Isometric hamstring heel dig', 'strength', '{healing}', '{hamstring}', '5 × 10 sec each side', null,
   'A gentle first strength exercise after a hamstring strain.',
   '{"Lie on your back with one knee bent and heel on the floor.","Dig your heel down and pull it toward you without letting it move.","Use only as much effort as is pain-free, then relax."}', true),
  (null, 'Bridge walkout', 'strength', '{prevention}', '{hamstring,glute}', '3 × 6', null,
   'Loads the hamstrings at longer lengths in a controlled way.',
   '{"Lift into a glute bridge.","Walk your heels out in small steps as far as you can keep your hips up.","Walk them back in and lower."}', false),
  (null, 'Sliding leg curl', 'strength', '{healing,prevention}', '{hamstring,glute}', '3 × 8', 'Sliders or towel on a smooth floor',
   'Strengthens the hamstrings as knee benders, which bridges alone miss.',
   '{"Lie on your back with heels on sliders and hips lifted.","Slowly slide your heels away until your legs are nearly straight.","Pull them back in while keeping your hips up."}', false),

  -- Knee
  (null, 'Heel slide', 'mobility', '{healing}', '{knee}', '2 × 15 each side', null,
   'Restores knee bending after injury or surgery.',
   '{"Lie on your back with your legs straight.","Slide one heel toward your buttock, bending the knee as far as is comfortable.","Slide it back out."}', true),
  (null, 'Peterson step-up', 'strength', '{healing,prevention}', '{knee,quad}', '3 × 12 each side', 'Low step',
   'Targets the inner quad, which helps the kneecap track well.',
   '{"Stand with one foot on a low step, heel raised.","Push through the ball of that foot to straighten the knee and lift your body.","Lower slowly."}', true),
  (null, 'Split squat', 'strength', '{prevention}', '{knee,quad,glute,hip}', '3 × 8 each side', 'Dumbbells (optional)',
   'Builds single-leg strength in the knee and hip.',
   '{"Stand in a long stride with your back heel lifted.","Lower your back knee toward the floor, keeping your front knee over your foot.","Push through the front foot to stand back up."}', true),
  (null, 'Lateral step-down', 'stability', '{healing,prevention}', '{knee,hip,quad}', '3 × 10 each side', 'Step',
   'Like a step-down, but sideways, demanding even more knee and hip control.',
   '{"Stand side-on on a step on one leg.","Slowly lower the outside heel toward the floor, keeping the standing knee over your toes.","Tap and come back up."}', true),
  (null, 'Mini squat', 'strength', '{healing}', '{knee,quad,glute}', '3 × 15', 'Chair or counter for balance',
   'A partial squat that strengthens the legs while staying in a pain-free range.',
   '{"Stand with feet hip-width apart, holding something light for balance.","Bend your knees about a quarter of the way down, hips back.","Stand back up, squeezing your glutes."}', false),

  -- Calf
  (null, 'Wall calf stretch', 'stretch', '{healing,prevention}', '{calf,ankle_foot}', '3 × 30 sec each side', null,
   'Stretches the upper calf, which can pull on the Achilles and arch when tight.',
   '{"Face a wall with hands on it, one foot back.","Keep the back leg straight and heel down.","Lean forward until you feel the stretch in the back calf."}', true),
  (null, 'Soleus stretch', 'stretch', '{healing,prevention}', '{calf,ankle_foot}', '3 × 30 sec each side', null,
   'Stretches the lower calf muscle that a straight-leg stretch misses.',
   '{"Stand as for the wall calf stretch.","Bend the back knee while keeping its heel down.","Lean in until you feel a stretch low in the calf."}', true),
  (null, 'Single-leg calf raise', 'strength', '{healing,prevention}', '{calf,ankle_foot}', '3 × 15 each side', null,
   'Builds calf and Achilles strength for running and jumping.',
   '{"Stand on one foot holding something for balance.","Rise as high as you can onto the ball of the foot.","Lower slowly."}', true),
  (null, 'Seated soleus raise', 'strength', '{healing,prevention}', '{calf,ankle_foot}', '3 × 20', 'Weight on your knees (optional)',
   'Strengthens the soleus, which takes much of the load when running.',
   '{"Sit with knees bent 90° and feet flat, weight resting on your knees.","Lift your heels as high as you can.","Lower slowly."}', false),

  -- Ankle and foot
  (null, 'Band ankle eversion', 'strength', '{healing,prevention}', '{ankle_foot}', '3 × 15 each side', 'Resistance band',
   'Strengthens the outer ankle muscles that guard against rolling an ankle.',
   '{"Sit with your leg straight and a band around your forefoot, anchored to the inside.","Turn your foot outward against the band, moving only the ankle.","Return slowly."}', true),
  (null, 'Band ankle inversion', 'strength', '{healing}', '{ankle_foot}', '3 × 15 each side', 'Resistance band',
   'Strengthens the inner ankle and arch support muscles.',
   '{"Sit with your leg straight and a band around your forefoot, anchored to the outside.","Turn your foot inward against the band, moving only the ankle.","Return slowly."}', true),
  (null, 'Towel scrunch', 'strength', '{healing}', '{ankle_foot}', '3 × 1 min each foot', 'Towel',
   'Works the small foot muscles that support the arch.',
   '{"Sit with your foot flat on a towel on a smooth floor.","Curl your toes to pull the towel toward you.","Spread it back out and repeat."}', true),
  (null, 'Plantar fascia stretch', 'stretch', '{healing}', '{ankle_foot}', '3 × 30 sec each foot', null,
   'Eases heel pain from plantar fasciitis, especially before the first steps of the morning.',
   '{"Sit and cross one foot over the other knee.","Pull your toes back toward your shin until you feel a stretch along the arch.","Hold, then relax."}', true),
  (null, 'Tibialis raise', 'strength', '{prevention}', '{ankle_foot,calf}', '3 × 15', 'Wall',
   'Strengthens the front of the shin. Helps with shin splints.',
   '{"Lean your back against a wall with your heels a foot or so in front of you.","Lift your toes as high as you can.","Lower slowly."}', false),
  (null, 'Heel walk', 'strength', '{prevention}', '{ankle_foot,calf}', '3 × 20 m', null,
   'Builds shin and ankle strength while walking.',
   '{"Lift your toes and walk on your heels only.","Keep your knees fairly straight and stay tall.","Walk slowly and steadily."}', false),
  (null, 'Star excursion balance', 'stability', '{healing,prevention}', '{ankle_foot,knee,hip}', '2 rounds each side', null,
   'A reaching balance drill used to retrain the ankle after sprains.',
   '{"Stand on one leg in the middle of an imaginary star.","Reach the other foot as far as you can forward, to the side and behind, tapping lightly.","Return to center each time without putting weight on the reaching foot."}', true)
on conflict ((lower(name))) where user_id is null do nothing;
